import json
import numpy as np

test_input = np.array([
    [1, 6, 6, 6, 6, 7],
    [1, 6, 1, 1, 6, 1],
    [1, 1, 1, 6, 6, 1],
    [7, 7, 6, 6, 6, 1],
    [7, 1, 6, 6, 1, 1],
    [6, 1, 6, 1, 7, 6]
])

def rot90_cw(m): return np.rot90(m, k=3)
def rot180(m): return np.rot90(m, k=2)
def rot270_cw(m): return np.rot90(m, k=1)

# Try each quadrant being a 6x6 tile of 6x6 individual 6x6 blocks
# Each quadrant is a single 12x12 region, but composed differently

# Actually - what if we construct output as:
# 4 rows of 6 tiles each, where each tile is alternating rotation patterns?

output = np.zeros((24, 24), dtype=int)
# Row 0 of 6x6 tiles
for c in range(4):
    if c % 2 == 0:
        output[0:6, c*6:(c+1)*6] = test_input
    else:
        output[0:6, c*6:(c+1)*6] = rot90_cw(test_input)

# Row 1 of 6x6 tiles - inverted pattern
for c in range(4):
    if c % 2 == 0:
        output[6:12, c*6:(c+1)*6] = test_input
    else:
        output[6:12, c*6:(c+1)*6] = rot270_cw(test_input)

# Row 2 - 180
for c in range(4):
    output[12:18, c*6:(c+1)*6] = rot180(test_input)

# Row 3 - back to 0 and 90
for c in range(4):
    if c % 2 == 0:
        output[18:24, c*6:(c+1)*6] = test_input
    else:
        output[18:24, c*6:(c+1)*6] = rot90_cw(test_input)

print(f"Shape: {output.shape}")
print("Row 0 (should have TL rotated):")
print(output[:6, :])
print("\nSubmission:")
print(json.dumps({"action": "submit", "grid": output.tolist()}))

